module proportions_solver (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    input [7:0] arr_7,\n    input [7:0] arr_8,\n    input [7:0] arr_9,\n    input [7:0] arr_10,\n    input [7:0] arr_11,\n    input [7:0] arr_12,\n    input [7:0] arr_13,\n    input [7:0] arr_14,\n    input [7:0] arr_15,\n    input [7:0] arr_16,\n    input [7:0] arr_17,\n    input [7:0] arr_18,\n    input [7:0] arr_19,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] COMPUTE = 3'd2;\n    localparam [2:0] FINISH = 3'd3;\n\n    reg [2:0] state;\n    reg [31:0] count;\n    reg [15:0] cycle_count;\n    localparam [15:0] MAX_CYCLES = 16'd1000;\n\n    // Problem variables\n    reg [7:0] p1;\n    reg [7:0] p2;\n    reg [7:0] p3;\n    reg [7:0] u;\n    reg [7:0] d;\n    reg [7:0] p4;\n    reg condition_met;\n    reg continue_flag;\n\n    integer i;  // For-loop index\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset ALL registers\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            count <= 32'd0;\n            cycle_count <= 16'd0;\n            p1 <= 8'd0;\n            p2 <= 8'd0;\n            p3 <= 8'd0;\n            p4 <= 8'd0;\n            u <= 8'd0;\n            d <= 8'd0;\n            condition_met <= 1'b0;\n            continue_flag <= 1'b1;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_count <= 16'd0;\n                    count <= 32'd0;\n                    if (start) state <= INIT;\n                end\n\n                INIT: begin\n                    // Initialize computation\n                    continue_flag <= 1'b1;\n                    p1 <= 8'd0;\n                    state <= COMPUTE;\n                end\n\n                COMPUTE: begin\n                    cycle_count <= cycle_count + 16'd1;\n\n                    // Break condition if max cycles reached\n                    if (cycle_count >= MAX_CYCLES) begin\n                        continue_flag <= 1'b0;\n                    end\n\n                    if (continue_flag) begin\n                        // Algorithm implementation\n                        condition_met = 1'b0;\n\n                        // Nested loops simulation\n                        if (p1 <= arr_0) begin\n                            p2 = 0;\n                            p3 = 0;\n                            u = 0;\n                            d = 0;\n\n                            while (p2 <= arr_5 && continue_flag) begin\n                                while (p3 <= arr_10 && continue_flag) begin\n                                    while (u <= arr_15 && continue_flag) begin\n                                        while (d <= arr_18 && continue_flag) begin\n                                            p4 = (p1*arr_1 + p2*arr_6 + p3*arr_11) / arr_16;\n                                            if (p4 <= arr_19 && (p1*arr_2 + p2*arr_7 + u*arr_12) % arr_17 == 0\n                                                && (p3*arr_3 + p4*arr_8 + d*arr_13) % arr_14 == 0\n                                                && (u*arr_4 + d*arr_9) <= 100) begin\n                                                    count <= count + 1;\n                                            end\n\n                                            // Update variables for next iteration\n                                            d = d + 1;\n                                            cycle_count <= cycle_count + 1;\n                                            if (cycle_count >= MAX_CYCLES) continue_flag <= 1'b0;\n                                        end\n                                        d = 0;\n                                        u = u + 1;\n                                    end\n                                    u = 0;\n                                    p3 = p3 + 1;\n                                end\n                                p3 = 0;\n                                p2 = p2 + 1;\n                            end\n                            p2 = 0;\n                            p1 = p1 + 1;\n                        end\n\n                        // After computation\n                        result <= count;\n                        state <= FINISH;\n                    end else begin\n                        state <= FINISH;\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule